style.css:
@-moz-document domain("jkanime.net") {
/* 1. FONDO DE JKANIME: Rosa Pastel con Círculos Blancos */
    body, 
    html, 
    .wrapper, 
    #wrapper,
    header, 
    .bg-dark, 
    .box, 
    .main-content, 
    .sidebar,
    .bg-custom,
    [style*="background-color"] {
        background-color: #FFDEE9 !important; /* Tu hermoso Rosa Pastel de base */
        background-image: radial-gradient(#FFFFFF 12%, transparent 12%),
                          radial-gradient(#FFFFFF 12%, transparent 12%) !important;
        background-size: 24px 24px !important; /* Lunares pequeños y estéticos */
        background-position: 0 0, 12px 12px !important;
        background-attachment: fixed !important;
    }

    /* Limpieza total de fondos negros, grises y azules oscuros de la página */
    .anime-container, .header-navigation, .footer, .list-episodes, .box-content,
    .navbar, .dropdown-menu, .navigation-bar, .card, .widget, .hero-area {
        background: transparent !important;
        background-color: transparent !important;
        border: none !important;
    }

    /* 2. TEXTOS, TÍTULOS Y COMENTARIOS: Letras Café Clarito y Cursivas */
    h1, h2, h3, h4, h5, h6, p, span, div, li, a, .title, .episode, .anime-title, .comment-text {
        color: #A0522D !important; /* Tu Café Clarito bien bonito */
        font-family: 'Georgia', 'Lucida Handwriting', cursive !important; /* Cursiva legible */
        font-style: italic !important;
        /* Delineado blanco fino para que el café se lea perfecto sobre el fondo rosa */
        text-shadow: -1px -1px 0 #FFFFFF, 1px -1px 0 #FFFFFF, -1px 1px 0 #FFFFFF, 1px 1px 0 #FFFFFF !important;
    }

    /* Nos aseguramos de que los enlaces mantengan el mismo tono café */
    a:link, a:visited, a:hover {
        color: #A0522D !important;
        text-decoration: none !important;
    }

    /* 3. LOGO DE JKANIME: Destellos en Amarillo Pastel */
    /* Como el logo original es una imagen fija oscura, le ponemos un filtro mágico para volverlo amarillo pastel tierno */
    .logo img, .navbar-brand img, [alt*="jkanime"], [alt*="JKAnime"] {
        filter: hue-rotate(60deg) brightness(1.6) sepia(0.5) saturate(1.5) !important;
    }

    /* 4. BUSCADOR SUPERIOR E ICONOS: Rosa Pastel */
    #search-form, 
    .search-box, 
    input[type="text"], 
    input[name="q"], 
    .form-control,
    .search-input {
        background-color: #FFB7CE !important; /* Tu Rosa Pastel indicado */
        border: 2px solid #FFFFFF !important;
        border-radius: 20px !important;
        color: #FFFFFF !important; /* Letras blancas al escribir en el buscador */
    }

    /* Texto de guía dentro del buscador */
    input::placeholder, .form-control::placeholder {
        color: rgba(255, 255, 255, 0.8) !important;
    }

    /* Iconos generales (La lupita de buscar, botones de reproducción, redes sociales) */
    svg, path, .fa, .fas, .far, yt-icon, .icon, button.btn-search svg {
        fill: #FFB7CE !important; /* Rosa Pastel */
        color: #FFB7CE !important;
    }

    /* 5. DETALLES EXTRAS: Botones de episodios y géneros en Amarillo Pastel */
    .btn-custom, 
    .anime-genre, 
    .badge, 
    .status-label,
    .next-episode-btn,
    .solotexto a {
        background-color: #FFF59D !important; /* Lindo Amarillo Pastel */
        border: 2px dashed #FFB7CE !important; /* Marquito de guiones rosa */
        color: #4A4A4A !important; /* Letras oscuras para leer bien en el amarillo */
        border-radius: 15px !important;
        padding: 4px 10px !important;
        display: inline-block !important;
    }
}
